onClick:
{{
  (async () => {
    try {
      showAlert('⏳ Suppression dans Pennylane en cours...', 'info');

      // 1. Suppression dans Pennylane
      await Pennylane_Supprimer_Facture.run({
        id_facture: Get_Facture_ById.data[0]?.ID_Facture || Get_Facture_ById.data[0]?.ID_Pennylane
      });

      // 2. Remise à zéro en base de données (Statut -> "À facturer")
      await Reset_BL_A_Facturer.run({
        id_bl: Get_Facture_ById.data[0]?.ID_BL
      });

      showAlert('✅ Facture annulée et remise à l\'état "À facturer" !', 'success');

      // 3. Redirection automatique vers la fiche du Bon de Livraison
      await navigateTo('Détail Bon de Livraison', { 
        id: Get_Facture_ById.data[0]?.ID_BL 
      });

    } catch (err) {
      showAlert('❌ Erreur de suppression : ' + err.message, 'error');
    }
  })()
}}
